WITH filtered AS (SELECT *, TRIM(device) AS clean_device, DATE_TRUNC('WEEK', started_at) AS started_at_period FROM sessions WHERE customer_id IS NOT NULL AND country IS NOT DISTINCT FROM 'SG'), filtered_sessions AS (SELECT *, DATE_FORMAT(started_at_period, 'yyyy-MM') AS started_at_period_label FROM filtered WHERE started_at >= TIMESTAMP '2023-06-12 05:00:00' AND country != 'US'), not_flagged AS (SELECT s.* FROM filtered_sessions s WHERE EXISTS (SELECT 1 FROM web_events ch WHERE ch.session_id = s.id AND ch.event_type IN ('click', 'purchase'))), joined AS (SELECT a.*, b.age, b.signup_date FROM not_flagged a LEFT JOIN customers b ON a.customer_id = b.id), latest_match AS (SELECT s.*, latest.duration_sec, latest.event_type FROM joined s LEFT JOIN LATERAL (SELECT c.duration_sec, c.event_type FROM web_events c WHERE c.session_id = s.id ORDER BY c.duration_sec DESC, c.id DESC LIMIT 1) latest ON TRUE), matched_keys AS (SELECT customer_id FROM latest_match INTERSECT ALL SELECT customer_id FROM sessions WHERE browser IN ('Firefox', 'Chrome', 'Safari')), kept_rows AS (SELECT s.* FROM latest_match s INNER JOIN matched_keys k ON s.customer_id = k.customer_id), not_flagged_sessions AS (SELECT s.* FROM kept_rows s WHERE NOT EXISTS (SELECT 1 FROM web_events c WHERE c.session_id = s.id AND c.event_time < s.signup_date)) SELECT browser, started_at, country, started_at_period, started_at_period_label, age, signup_date, duration_sec, event_type FROM not_flagged_sessions;
